define("report_rubricgrading/pivot_header",[],function(){"use strict";var G="rubricpivot-groupheader";var applyGroupHeaders=function(table){var thead=table.querySelector("thead");if(!thead)return;var ex=thead.querySelector("."+G);if(ex)ex.parentNode.removeChild(ex);var subRow=thead.querySelector("tr");if(!subRow)return;var cells=Array.from(subRow.querySelectorAll("th,td"));if(!cells.length)return;var groups=[];cells.forEach(function(th,idx){var text=th.textContent.trim();var sep=text.lastIndexOf(" - ");var last=groups[groups.length-1];if(idx===0){groups.push({label:"Student",count:1});}else if(sep>-1){var gname=text.substring(0,sep);var col=text.substring(sep+3);th.textContent=col;if(last&&last.isCriterion&&last.label===gname){last.count++;}else{groups.push({label:gname,count:1,isCriterion:true});}}else{if(last&&last.isGradeSummary){last.count++;}else{groups.push({label:"Grade summary",count:1,isGradeSummary:true});}}});var groupRow=document.createElement("tr");groupRow.className=G;groups.forEach(function(g){var th=document.createElement("th");th.textContent=g.label;th.colSpan=g.count;groupRow.appendChild(th);});thead.insertBefore(groupRow,subRow);};var init=function(){var wrapper=document.getElementById("rubricpivot-table-wrap");if(!wrapper)return;var transform=function(){var t=wrapper.querySelector("table");if(t)applyGroupHeaders(t);};transform();var observer=new MutationObserver(function(mutations){var ownOnly=mutations.every(function(m){return Array.from(m.addedNodes).every(function(n){return n.nodeType===1&&n.classList&&n.classList.contains(G);});});if(!ownOnly)transform();});observer.observe(wrapper,{childList:true,subtree:true});};return{init:init};});
